;(function($){$.fn.DB_springMove=function(s){var t={dir:'y',mirror:1,radius:20,motionSpeed:0.05,intervalTimer:30,over:'move'};$.extend(t,s);return this.each(function(){var p=$(this);var q=0;var r=1;init();function init(){setCss();setMouseEvent();setEnterFrame()};function setCss(){p.css({'position':'absolute'})};function setMouseEvent(){if(t.over=='stop'){p.bind('mouseenter',function(){r=0}).bind('mouseleave',function(){r=1})}};function setAnimation(){radius=Math.sin(q)*t.radius;if(r){q+=t.motionSpeed};if(t.dir=='x'){p.css({'margin-left':radius*t.mirror})}else{p.css({'margin-top':radius*t.mirror})}}function setEnterFrame(){timerId=setInterval(setAnimation,t.intervalTimer)}})}})(jQuery);

